// ============================================================================
// RAII Introspection Registry
// ============================================================================

/// Outcome of an unregister operation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnregisterOutcome {
    /// The handle was successfully unregistered.
    Unregistered,
    /// The handle was not found (no-op).
    Missing,
}

/// Outcome of a register operation when overlap is detected.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegisterOverlapOutcome {
    /// Registration was rejected due to conflict with existing registration.
    Conflict,
    /// Registration replaced the existing one with a new epoch.
    Replaced {
        /// The epoch of the replaced registration.
        old_epoch: u64,
        /// The epoch of the new registration.
        new_epoch: u64,
    },
}

/// Epoch-based handle for an introspection registration.
///
/// When dropped, the handle is automatically unregistered from the registry.
#[derive(Debug)]
pub struct InspectHandle {
    run: RunId,
    epoch: u64,
    registry: std::sync::Arc<std::sync::Mutex<std::collections::HashMap<RunId, u64>>>,
}

impl InspectHandle {
    /// Returns the run identifier associated with this handle.
    #[must_use]
    pub fn run(&self) -> RunId {
        self.run
    }

    /// Returns the epoch of this handle.
    #[must_use]
    pub fn epoch(&self) -> u64 {
        self.epoch
    }
}

impl Drop for InspectHandle {
    fn drop(&mut self) {
        if let Ok(mut guard) = self.registry.lock() {
            // Only remove if the epoch matches (handles stale drops correctly)
            if let Some(current_epoch) = guard.get(&self.run)
                && *current_epoch == self.epoch
            {
                guard.remove(&self.run);
            }
        }
    }
}

/// Registry for RAII-based introspection handles.
///
/// Provides epoch-based registration with automatic cleanup on guard drop.
/// Does NOT create global mutable run state - each registry instance is independent.
#[derive(Default)]
pub struct IntrospectionRegistry {
    inner: std::sync::Arc<std::sync::Mutex<std::collections::HashMap<RunId, u64>>>,
    next_epoch: u64,
}

impl IntrospectionRegistry {
    /// Creates a new empty registry.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Acquires the registry's inner mutex, recovering from any prior
    /// poison state. The standard `Mutex::lock` returns `PoisonError`
    /// forever once a holder panics; this helper mirrors the recovery
    /// pattern already used by `action_queue` so the admission gate does
    /// not stay permanently disabled after a panic.
    fn lock_or_recover(
        inner: &std::sync::Arc<std::sync::Mutex<std::collections::HashMap<RunId, u64>>>,
    ) -> std::sync::MutexGuard<'_, std::collections::HashMap<RunId, u64>> {
        match inner.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        }
    }

    /// Registers a handle for the given run.
    ///
    /// Returns the handle guard on success. Recovers transparently from
    /// a poisoned mutex so a single panicking holder cannot permanently
    /// disable the admission gate (RA-014).
    pub fn register(&mut self, run: RunId) -> RuntimeResult<InspectHandle> {
        let mut guard = Self::lock_or_recover(&self.inner);

        // Check if already registered
        if guard.contains_key(&run) {
            return Err(crate::RuntimeError::RunAlreadyExists);
        }

        let epoch = self.next_epoch;
        self.next_epoch = self
            .next_epoch
            .checked_add(1)
            .ok_or(crate::RuntimeError::IntrospectionEpochExhausted)?;
        guard.insert(run, epoch);

        Ok(InspectHandle {
            run,
            epoch,
            registry: self.inner.clone(),
        })
    }

    /// Registers a handle for the given run, allowing epoch replacement on conflict.
    ///
    /// Returns outcome indicating whether registration succeeded, conflicted, or was replaced.
    pub fn register_with_overlap_policy(
        &mut self,
        run: RunId,
    ) -> RuntimeResult<(InspectHandle, Result<(), RegisterOverlapOutcome>)> {
        let mut guard = Self::lock_or_recover(&self.inner);

        let (outcome, epoch) = if let Some(&old_epoch) = guard.get(&run) {
            // Overlap detected - replace with new epoch
            let new_epoch = self.next_epoch;
            self.next_epoch = self
                .next_epoch
                .checked_add(1)
                .ok_or(crate::RuntimeError::IntrospectionEpochExhausted)?;
            guard.insert(run, new_epoch);
            (
                Err(RegisterOverlapOutcome::Replaced {
                    old_epoch,
                    new_epoch,
                }),
                new_epoch,
            )
        } else {
            // No overlap - insert with new epoch
            let epoch = self.next_epoch;
            self.next_epoch = self
                .next_epoch
                .checked_add(1)
                .ok_or(crate::RuntimeError::IntrospectionEpochExhausted)?;
            guard.insert(run, epoch);
            (Ok(()), epoch)
        };

        Ok((
            InspectHandle {
                run,
                epoch,
                registry: self.inner.clone(),
            },
            outcome,
        ))
    }

    /// Unregisters a handle for the given run.
    ///
    /// Returns whether the handle was found and unregistered.
    pub fn unregister(&mut self, run: RunId) -> RuntimeResult<UnregisterOutcome> {
        let mut guard = Self::lock_or_recover(&self.inner);

        if guard.remove(&run).is_some() {
            Ok(UnregisterOutcome::Unregistered)
        } else {
            Ok(UnregisterOutcome::Missing)
        }
    }

    /// Unregisters all handles.
    ///
    /// Returns the count of handles removed.
    pub fn unregister_all(&mut self) -> RuntimeResult<usize> {
        let mut guard = Self::lock_or_recover(&self.inner);
        let count = guard.len();
        guard.clear();
        Ok(count)
    }

    /// Returns whether a run is currently visible to introspection.
    #[must_use]
    pub fn is_visible(&self, run: RunId) -> bool {
        match self.inner.lock() {
            Ok(guard) => guard.contains_key(&run),
            Err(poisoned) => poisoned.into_inner().contains_key(&run),
        }
    }
}

#[cfg(test)]
impl IntrospectionRegistry {
    /// Returns a clone of the inner `Arc<Mutex<...>>` for tests that need
    /// to poison the registry from another thread. Production code MUST
    /// NOT use this — it is compiled out of release builds.
    pub(crate) fn inner_arc_for_test(
        &self,
    ) -> std::sync::Arc<std::sync::Mutex<std::collections::HashMap<RunId, u64>>> {
        self.inner.clone()
    }
}

/// Snapshot formatting stays cold path (no computation on hot path).
pub struct InspectSnapshotFormatter;

impl InspectSnapshotFormatter {
    /// Formats a snapshot response into a string representation.
    ///
    /// This is a cold-path operation - called only when formatting output,
    /// not during the hot path of inspect operations.
    #[must_use]
    pub fn format_snapshot(response: &InspectResponse) -> String {
        match response {
            InspectResponse::Found(snap) => {
                format!(
                    "InspectSnapshot {{ run: {:?}, correlation: {}, pc: {:?}, executed: {} }}",
                    snap.run, snap.correlation, snap.pc, snap.executed
                )
            }
            InspectResponse::NotFound { run, correlation } => {
                format!(
                    "NotFound {{ run: {:?}, correlation: {} }}",
                    run, correlation
                )
            }
        }
    }
}

/// Maximum bounded command queue capacity per shard.
pub const MAX_COMMAND_QUEUE_CAPACITY: usize = 65_536;

/// Returns true when a command queue capacity is inside the supported domain.
#[must_use]
pub const fn is_valid_command_queue_capacity(capacity: usize) -> bool {
    capacity > 0 && capacity <= MAX_COMMAND_QUEUE_CAPACITY
}

// ============================================================================
// ShardCommandQueue — domain wrapper around ArrayQueue<ShardCommand>
// ============================================================================

/// Domain-named wrapper around `crossbeam_queue::ArrayQueue<ShardCommand>`.
///
/// Provides a bounded, non-blocking command queue with domain-specific terminology
/// (`enqueue`, `pop`, `is_full`, `remaining_capacity`) and proper error taxonomy
/// (`RuntimeError::QueueFull`). This wrapper establishes the `ShardCommand` queue
/// as a first-class domain boundary rather than a raw field.
pub struct ShardCommandQueue {
    inner: ArrayQueue<ShardCommand>,
    /// Stored capacity to satisfy POST-001 and INV-001 invariants.
    capacity: usize,
}

impl ShardCommandQueue {
    /// Creates a new `ShardCommandQueue` with the given capacity.
    ///
    /// # Errors
    /// Returns `RuntimeError::CommandQueueCapacityExceeded` if `capacity` is 0
    /// or exceeds `MAX_COMMAND_QUEUE_CAPACITY`.
    pub fn new(capacity: usize) -> RuntimeResult<Self> {
        if !is_valid_command_queue_capacity(capacity) {
            return Err(crate::RuntimeError::CommandQueueCapacityExceeded {
                capacity,
                max: MAX_COMMAND_QUEUE_CAPACITY,
            });
        }
        Ok(Self {
            inner: ArrayQueue::new(capacity),
            capacity,
        })
    }

    /// Creates a command queue from an already-accepted shard configuration.
    ///
    /// `Shard::new` has historically been infallible and accepted `ShardConfig`
    /// by value. The validated constructor for externally supplied capacity is
    /// `ShardConfig::new`; this helper preserves `Shard::new`'s existing shape
    /// while placing the raw queue construction behind the domain wrapper.
    pub(crate) fn from_config(config: ShardConfig) -> Self {
        Self {
            inner: ArrayQueue::new(config.command_queue_capacity),
            capacity: config.command_queue_capacity,
        }
    }

    /// Enqueues a command. Returns `Ok(())` if the command was enqueued, or
    /// `Err(RuntimeError::QueueFull)` if the queue is at capacity.
    ///
    /// This operation is non-blocking and never allocates on failure.
    pub fn enqueue(&self, cmd: ShardCommand) -> RuntimeResult<()> {
        self.inner
            .push(cmd)
            .map_err(|_| crate::RuntimeError::QueueFull)
    }

    /// Dequeues the frontmost command, if any.
    ///
    /// Returns `Some(cmd)` in FIFO order, or `None` if the queue is empty.
    pub fn pop(&self) -> Option<ShardCommand> {
        self.inner.pop()
    }

    /// Returns the number of commands currently in the queue.
    #[must_use]
    pub fn len(&self) -> usize {
        self.inner.len()
    }

    /// Returns `true` if the queue contains no commands.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.inner.is_empty()
    }

    /// Returns the capacity of this queue (set at construction).
    #[must_use]
    pub fn capacity(&self) -> usize {
        self.capacity
    }

    /// Returns the number of remaining free slots in the queue.
    #[must_use]
    pub fn remaining_capacity(&self) -> usize {
        self.capacity.saturating_sub(self.inner.len())
    }

    /// Returns `true` if the queue is at capacity.
    #[must_use]
    pub fn is_full(&self) -> bool {
        self.inner.len() == self.capacity
    }

    /// Returns the compile-time bounded capacity limit (65536).
    ///
    /// This is the maximum capacity any `ShardCommandQueue` can be configured with.
    #[must_use]
    pub const fn bounded_capacity() -> usize {
        MAX_COMMAND_QUEUE_CAPACITY
    }
}

/// Private aggregate for run membership side data. Runtime lifecycle state and
/// terminal membership are co-owned here so terminal identity cannot coexist
/// with stale resumability state.
pub(crate) struct RunAggregate {
    runtime_states: IndexMap<RunId, RuntimeState>,
    checked_out_runs: IndexSet<RunId>,
    terminal_runs: IndexSet<RunId>,
    pending_timers: IndexMap<RunId, PendingTimer>,
    pending_actions: IndexMap<RunId, ActionTicket>,
}

impl RunAggregate {
    pub(crate) fn new() -> Self {
        Self {
            runtime_states: IndexMap::new(),
            checked_out_runs: IndexSet::new(),
            terminal_runs: IndexSet::new(),
            pending_timers: IndexMap::new(),
            pending_actions: IndexMap::new(),
        }
    }

    pub(crate) fn reserve_runtime_state_slot(
        &mut self,
        run: RunId,
        capacity: usize,
    ) -> RuntimeResult<()> {
        if self.runtime_states.contains_key(&run) {
            return Ok(());
        }
        if self.runtime_states.len() >= capacity {
            return Err(crate::RuntimeError::ActiveRunCapacityExceeded { capacity });
        }
        self.runtime_states
            .try_reserve(1)
            .map_err(|_| crate::RuntimeError::ActiveRunCapacityExceeded { capacity })
    }

    pub(crate) fn runtime_state_get(&self, run: RunId) -> Option<RuntimeState> {
        self.runtime_states.get(&run).copied()
    }

    /// Inserts a non-terminal runtime state only when the run is not retained
    /// as terminal. Terminal failures are represented by `terminal_runs`, not a
    /// stale `RuntimeState::Failed` entry.
    pub(crate) fn runtime_state_insert(
        &mut self,
        runs: &IndexMap<RunId, RunState>,
        run: RunId,
        state: RuntimeState,
        capacity: usize,
    ) -> RuntimeResult<Option<RuntimeState>> {
        if state == RuntimeState::Failed {
            return Err(crate::RuntimeError::UnsupportedOperation {
                operation: "runtime_state_failed_terminal_split",
            });
        }
        if self.terminal_contains(run) {
            return Err(crate::RuntimeError::RunAlreadyExists);
        }
        if !runs.contains_key(&run) && !self.checked_out_contains(run) {
            return Err(crate::RuntimeError::RunNotFound);
        }
        self.reserve_runtime_state_slot(run, capacity)?;
        Ok(self.runtime_states.insert(run, state))
    }

    pub(crate) fn runtime_state_remove(&mut self, run: RunId) {
        let _removed = self.runtime_states.swap_remove(&run);
    }

    /// Clears only runtime lifecycle state for terminal `RuntimeEvent` apply.
    /// Checked-out ownership and pending boundaries are cleaned by terminal
    /// lifecycle paths, not by this state-machine transition.
    pub(crate) fn runtime_state_terminal_clear(&mut self, run: RunId) {
        self.runtime_state_remove(run);
    }

    pub(crate) fn checked_out_len(&self) -> usize {
        self.checked_out_runs.len()
    }

    pub(crate) fn checked_out_contains(&self, run: RunId) -> bool {
        self.checked_out_runs.contains(&run)
    }

    pub(crate) fn checked_out_iter(&self) -> impl Iterator<Item = &RunId> {
        self.checked_out_runs.iter()
    }

    pub(crate) fn reserve_checked_out_slot(
        &mut self,
        run: RunId,
        capacity: usize,
    ) -> RuntimeResult<()> {
        if self.checked_out_contains(run) {
            return Ok(());
        }
        if self.checked_out_runs.len() >= capacity {
            return Err(crate::RuntimeError::ActiveRunCapacityExceeded { capacity });
        }
        self.checked_out_runs
            .try_reserve(1)
            .map_err(|_| crate::RuntimeError::ActiveRunCapacityExceeded { capacity })
    }

    pub(crate) fn checked_out_insert(&mut self, run: RunId, capacity: usize) -> RuntimeResult<()> {
        self.reserve_checked_out_slot(run, capacity)?;
        if self.checked_out_runs.insert(run) {
            Ok(())
        } else {
            Err(crate::RuntimeError::RunAlreadyExists)
        }
    }

    pub(crate) fn checked_out_remove(&mut self, run: RunId) {
        let _removed = self.checked_out_runs.swap_remove(&run);
    }

    pub(crate) fn terminal_contains(&self, run: RunId) -> bool {
        self.terminal_runs.contains(&run)
    }

    /// Retains terminal identity only after active run-state ownership has
    /// left `Shard::runs`, and clears runtime plus active-boundary side data
    /// for that run.
    pub(crate) fn terminal_insert(
        &mut self,
        runs: &IndexMap<RunId, RunState>,
        run: RunId,
        capacity: usize,
    ) -> RuntimeResult<bool> {
        if self.terminal_contains(run) {
            return Ok(false);
        }
        if runs.contains_key(&run) {
            return Err(crate::RuntimeError::RunAlreadyExists);
        }
        if !self.checked_out_contains(run) {
            return Err(crate::RuntimeError::RunNotFound);
        }
        self.reserve_terminal_slot(run, capacity)?;
        self.runtime_state_remove(run);
        self.checked_out_remove(run);
        let _removed_timer = self.pending_timers.swap_remove(&run);
        let _removed_action = self.pending_actions.swap_remove(&run);
        Ok(self.terminal_runs.insert(run))
    }

    pub(crate) fn terminal_remove(&mut self, run: RunId) {
        let _removed = self.terminal_runs.swap_remove(&run);
    }

    pub(crate) fn reserve_terminal_insert_slot(
        &mut self,
        run: RunId,
        capacity: usize,
    ) -> RuntimeResult<()> {
        if self.terminal_runs.contains(&run) {
            return Ok(());
        }
        if capacity == 0 {
            return Err(crate::RuntimeError::ActiveRunCapacityExceeded { capacity });
        }
        if self.terminal_runs.len() >= capacity {
            return Ok(());
        }
        self.terminal_runs
            .try_reserve(1)
            .map_err(|_| crate::RuntimeError::ActiveRunCapacityExceeded { capacity })
    }

    fn reserve_terminal_slot(&mut self, run: RunId, capacity: usize) -> RuntimeResult<()> {
        if self.terminal_runs.contains(&run) {
            return Ok(());
        }
        if capacity == 0 {
            return Err(crate::RuntimeError::ActiveRunCapacityExceeded { capacity });
        }
        if self.terminal_runs.len() >= capacity {
            let evicted = self.terminal_runs.iter().next().copied();
            if let Some(evicted) = evicted {
                let _removed = self.terminal_runs.shift_remove(&evicted);
            }
        }
        self.terminal_runs
            .try_reserve(1)
            .map_err(|_| crate::RuntimeError::ActiveRunCapacityExceeded { capacity })
    }

    pub(crate) fn run_is_live_for_boundary(
        &self,
        runs: &IndexMap<RunId, RunState>,
        run: RunId,
    ) -> bool {
        !self.terminal_contains(run) && (runs.contains_key(&run) || self.checked_out_contains(run))
    }

    pub(crate) fn pending_timer_len(&self) -> usize {
        self.pending_timers.len()
    }

    pub(crate) fn reserve_pending_timer_slot(
        &mut self,
        run: RunId,
        capacity: usize,
    ) -> RuntimeResult<()> {
        if self.pending_timers.contains_key(&run) {
            return Ok(());
        }
        if self.pending_timers.len() >= capacity {
            return Err(crate::RuntimeError::ActiveRunCapacityExceeded { capacity });
        }
        self.pending_timers
            .try_reserve(1)
            .map_err(|_| crate::RuntimeError::ActiveRunCapacityExceeded { capacity })
    }

    pub(crate) fn pending_timer_insert(
        &mut self,
        runs: &IndexMap<RunId, RunState>,
        capacity: usize,
        run: RunId,
        timer: PendingTimer,
    ) -> RuntimeResult<Option<PendingTimer>> {
        if !self.run_is_live_for_boundary(runs, run) {
            return Err(crate::RuntimeError::RunNotFound);
        }
        self.reserve_pending_timer_slot(run, capacity)?;
        Ok(self.pending_timers.insert(run, timer))
    }

    pub(crate) fn pending_timer_get(&self, run: RunId) -> Option<PendingTimer> {
        self.pending_timers.get(&run).copied()
    }

    pub(crate) fn pending_timer_clone(&self) -> IndexMap<RunId, PendingTimer> {
        self.pending_timers.clone()
    }

    pub(crate) fn pending_timer_remove(&mut self, run: RunId) -> Option<PendingTimer> {
        self.pending_timers.swap_remove(&run)
    }

    pub(crate) fn pending_timer_contains(&self, run: RunId) -> bool {
        self.pending_timers.contains_key(&run)
    }

    pub(crate) fn pending_timer_iter(&self) -> impl Iterator<Item = (&RunId, &PendingTimer)> {
        self.pending_timers.iter()
    }

    pub(crate) fn pending_timer_clear(&mut self) {
        self.pending_timers.clear();
    }

    pub(crate) fn pending_action_len(&self) -> usize {
        self.pending_actions.len()
    }

    pub(crate) fn reserve_pending_action_slot(
        &mut self,
        run: RunId,
        capacity: usize,
    ) -> RuntimeResult<()> {
        if self.pending_actions.contains_key(&run) {
            return Ok(());
        }
        if self.pending_actions.len() >= capacity {
            return Err(crate::RuntimeError::ActiveRunCapacityExceeded { capacity });
        }
        self.pending_actions
            .try_reserve(1)
            .map_err(|_| crate::RuntimeError::ActiveRunCapacityExceeded { capacity })
    }

    pub(crate) fn pending_action_insert(
        &mut self,
        runs: &IndexMap<RunId, RunState>,
        capacity: usize,
        run: RunId,
        ticket: ActionTicket,
    ) -> RuntimeResult<Option<ActionTicket>> {
        if !self.run_is_live_for_boundary(runs, run) {
            return Err(crate::RuntimeError::RunNotFound);
        }
        self.reserve_pending_action_slot(run, capacity)?;
        Ok(self.pending_actions.insert(run, ticket))
    }

    pub(crate) fn pending_action_get(&self, run: RunId) -> Option<ActionTicket> {
        self.pending_actions.get(&run).copied()
    }

    pub(crate) fn pending_action_clone(&self) -> IndexMap<RunId, ActionTicket> {
        self.pending_actions.clone()
    }

    pub(crate) fn pending_action_remove(&mut self, run: RunId) -> Option<ActionTicket> {
        self.pending_actions.swap_remove(&run)
    }

    pub(crate) fn pending_action_iter(&self) -> impl Iterator<Item = (&RunId, &ActionTicket)> {
        self.pending_actions.iter()
    }
}

/// Single-threaded shard owning all mutable run state.
pub struct Shard {
    pub(crate) command_queue: ShardCommandQueue,
    pub(super) runs: IndexMap<RunId, RunState>,
    pub(super) run_aggregate: RunAggregate,
