        let deadline = Instant::now();
        let timer = PendingTimer {
            step: vb_core::ids::StepIdx::ZERO,
            kind: PendingTimerKind::Wait,
            generation: 5,
            deadline,
        };
        assert!(timer.matches_authority(5, deadline, PendingTimerKind::Wait));
